) AS (
  VALUES 
    (205::BIGINT, 'Es el mejor profesor de física, de los pocos que no se atrasa en entregar notas de quices o exámenes, las clases son muy claras y ejemplifica todo lo posible, con ejercicios, simulaciones, y así, no tiene problema con la asistencia y ofrece toda la ayuda posible, repasos fuera de horario, etc'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'f26c7068fc52115585c87aa5a7575edf343bea53804bbb6f2f31db08dd9a2fe9'::TEXT, ARRAY[922]::BIGINT[]),
    (205::BIGINT, 'Cuesta mucho encontrar un buen profesor de física y Michael lo es! Trabaja siempre con presentaciones que él hizo y son demasiado útiles por toda la info que trae, eso sí, si no tienen tablet deben adaptarse de alguna manera porque va rápido y es mucha info. Usa buenos ejemplos y repite si hay dudas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, '4057f546a6646d37921510d373ff70db501d53e591dd1a2ad5e016a182375602'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Definitivamente el MEJOR profesor de toda la cátedra de física, evalúa muy bien, explica súper claro, da material extra y material hecho por él mismo que es todavía mejor que las presentaciones que da la misma cátedra, hace mucha práctica y siempre saca tiempo extra para hacer algún repaso de examen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f2f6bbcddc8feddefab151931d4d569a476a681caba6b44e22d4ccd61ccd3ee9'::TEXT, ARRAY[604, 630, 607, 631, 922]::BIGINT[]),
    (205::BIGINT, 'Es lo mejor que tiene el TEC. Si usted es el afortunado de matricular con él, ha desbloqueado lo mejor que tiene el TEC. Aprende, entiende y pasa. Si usted se queda con él, está en problemas serios, usted.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-11T00:00:00+00:00'::TIMESTAMPTZ, '27215aa1ffc75f7f150cb58c93efd62cd02332109d3225507e546f4d0103cb55'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Un profesor como pocos en el TEC, Física 2 es un curso de cuidado, pero con Michael fue bastante llevadero e incluso sencillo. El no suele dar el curso, pero en cualquier Fisica pedagogicamente el es el mejor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'fa89225bf2343c793515e36fe6b9c8f3b9cddde210d4616cee63f58c60bcd8fa'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Excelente profesor, siempre claro, amable y muy dedicado. Aprendí mucho en sus clases y quedé muy satisfecho. Califica suave/normal, los trabajos fueron muy faciles, en su mayoría ejercicios faciles y rapidos. No pasa asistencia, creo que solo se fija en la lista de teams de quienes se conectaron'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-05T00:00:00+00:00'::TIMESTAMPTZ, '4d9da83c7be5bb045050edc8a98ab36bdc942f78f920fa52c3f2b66e1666fa6c'::TEXT, ARRAY[922]::BIGINT[]),
    (205::BIGINT, 'El mejor profesor de la fisica en el TEC, explica clarisimo, contestaba mis dudas antes de que yo preguntara, califica suave, este hombre es perfeccion. Matriculate en cualquiera de sus cursos de una'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2026-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'd6e7e2bec0cb6b8d6ac5da5db2f5ee210c0769ecb728244b520af22585e15d5a'::TEXT, ARRAY[922]::BIGINT[]),
    (205::BIGINT, 'Un buen profe de física, ofrece bastante material e apoyo pero importante no conformase con esto, ofrece ayuda, da clasae de repaso y simplemente un profe bastante bueno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '50eded171aeec6bf381af57b449feb4639211cd35fab28a1f66e09f0dc6111c8'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Este profe es el mejor que tiene el TEC, como este mae no hay ninguno mejor. Él explica super bien y claro, ayuda un montón con las evaluaciones individuales. El mejor profe para llevar cualquier física y pasarla APRENDIENDO!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'b8d4a72cc396d508a57c2ac95aa92917a346922275dc1989ba34a906cedf2a1c'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Excelente profe, explica super bien, pero le recomiendo que tome notas por aparte para ir haciendo un resumen de todo, y con eso pasa super bien, hace clases de repaso, y de verdad se preocupa porque uno entienda, este profe hace que el curso se vuelva mucho mas facil, matricule con el'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'ef895bdc1d705647085af7fddebff33b66834a0ef2251e313f9e0f1f66fff1c8'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Super buen profe, demasiada ayuda, buenos repasos antes del examen, hay que decir que el curso no es fácil pero sus evaluaciones son muy claras y se entienden muy bien, no califica rudo los exámenes, pregunte lo mas que pueda el le gusta eso. Sin miedo matricule con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '06a174792578035089cb92bf9261d4e9e4c07a7175c2a6d610bfe0253cabc4d5'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es el mejor profesor para llevar cualquier física, es un amor de persona y explica excelente, califica lo justo, le importa que los estudiantes aprendan, y el porcentaje que tienen los profesores para evaluar, el lo evalúa tratando de que usted tenga todos los puntos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f7a247f82056a999b83536d69c345038bb3c93022e3703f20d7a52b7ac6f85f5'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Es de los mejores profes que he tenido, explica súper bien y se interesa porque los estudiantes entiendan. Física 2 es un curso pesado pero Cambronero hizo que lo pudiera entender bien'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '62ee4388fe66ff4e17400586bd07f9baede1f721caea38c2efdb83e0d2cffa65'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'De los mejores profes de Fisica, es una excelente persona, ayuda mucho en clase hace bastantes ejercicios, hace clases extra para el examen, explica super bien y es flexible con los quices y tareas, ir a consulta hasta para preguntar lo mas básico vale la pena, lo recomiendo mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '8ab09ab74910b93f38253281ac8815ed0ae4a5921acf1313956f093508fb9564'::TEXT, ARRAY[922]::BIGINT[]),
    (205::BIGINT, 'Se nota la vocación del profesor. Siempre hace lo posible para que todo quede claro, brinda mucho material de apoyo y se preocupa por dejar bases sólidas en los estudiantes. Califica de forma justa y los quices son sencillos. Siempre da una clase extra de repaso antes del examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, '2f2a34f3921f549957cb1299c83f2f5ed8c200b2e7bc0f8d7a2c4c99a3d34fd5'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es un amor. Es un verdadero profesor, porque su misión cada clase es explicar excelente para que los estudiantes entiendan la materia. Califica moderado en los exámenes, siempre está dispuesto a ayudar con tal de enseñar. Los quices son un queque, etc (cosas positivas) :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'b26f8cc5ddeb432e36c5d7c4cea7ffd0c44ef3903d76d4b890dcefa8b4185b08'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es agradable, ayuda mucho. Si la virtualidad no es problema, se puede matricular en esa modalidad.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e4cc1faa50d54636c42ec79a5fca3a0dfa2a67d71af7d90a2e222b5d56b1d91b'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El mejor profe para llevar física 1 virtual si usted logra poner atención en clase. Explica súper claro, tienes presentaciones ordenadas, da clases de repaso, no deja quices solo unas actividades que se contestan en la misma clase súper fáciles. Califica súper suave los exámenes, 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '64c4052b032c10cc82e8fe80cd50a109e7d37edcc139f224c42dcaf02ec8f0bd'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es de los mejores profes para física, si a usted le cuesta mucho concentrarse en la virtualidad pienselo dos veces, pero en general él es excelente califica demasiado suave aunque no le haya dado el problema da la mayoría de pts si teoricamente esta bien. No tiene quices.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-12-16T00:00:00+00:00'::TIMESTAMPTZ, '7a2134256a818ba96426b53347d95689dcb3f888dca14720195f9275b711c306'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Sinceramente si usted logra poner atención a clases virtuales, de fijo matricule con él. Excelente profe, da clases de repaso, contesta siempre dudas, califica suave en los exámenes y le ayuda mucho a uno, es muy empático y se tira buenos chistes. 100% recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '35d22ae0033c2ee8cfd38f88ae244a87e4b4de51f940c5d39884c188a269abd3'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'De los mejores profes con los que he tratado, se preocupa mucho por los estudiantes, siempre tiene muy buena actitud, da clases optativas de repaso para los parciales, explica super bien. Se los recomiendo mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, '53b2bd67ecc8407d967530c6d1683cef69e81b3bd26f7597ab77cf66cacd2506'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es un excelente profesor y hace muchas clases de repaso antes de los parciales, lo cual me parece excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-24T00:00:00+00:00'::TIMESTAMPTZ, '6b2c5ab991ced9f60df4809c5ed2f408a6dcde70c281bc5917b559610ff19e71'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Un profesor muy bueno y amable. Deja unas actividades que solo hay que hacerlas para ganarse el puntaje.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e0fd65f3eeeaa7f7f83e0b90ca7d94d3e7b558b9532b947cf72dbf7bb11e6ee1'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'No piense dos veces en matricular con el lab, las clases que se requieren hacer informes/experiencias las hace virtuales y hace cada paso y graba la clase por lo que se puede hacer con facilidad después. Califica un poco duro los informes pero en general es muy bueno y se preocupa por los estudiante'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0e473a26dcc2dabd74ec221ac282ef89c24205df022cdffd454d0ba2d16a25d8'::TEXT, ARRAY[607]::BIGINT[]),
    (205::BIGINT, 'El profe es muy bueno y explica muy bien, es una de las pocas buenas opciones que hay para Física I, lo único malo es que es virtual, entonces seguirle el ritmo en las clases puede ser difícil, y a veces cuesta mucho que conteste los mensajes. No califica duro y casi que regala los quices.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c7840e8b197bd27f01026bc7a650ccd2fa2041d68780e92ab0997b5d24e57911'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es un excelente profe, se preocupa por explicar bien la materia para que todos entiendan, y es el encargado de la Cátedra. Es virtual, pero si tienen la posibilidad de matricular con él no se van a arrepentir y utiliza presentaciones donde coloca toda la información importante para los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f7b54161c375b70c6e0c380825287165dbad819acfb67075a3485e63067be900'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Excelentes explicaciones, explica la materia de manera que se ve fácil y se entiende todo, además es muy atento con el estudiante y se asegura de que todos entiendan. Además el material de apoyo es excelente, tanto así que casi no hace falta hacer apuntes en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-12T00:00:00+00:00'::TIMESTAMPTZ, '1aa5e15e2e71c6bc80ab4cd28d320151d14f6628808f64d8cc7c67231fe3272f'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Muy buen profe, se procupa mucho por los estudiantes y brinda mucho apoyo'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-11-06T00:00:00+00:00'::TIMESTAMPTZ, '900416b8c7bb34226c8576fd1bc131ded7177b49c15158fe0050a643b3372c6e'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'De los mejores profes del tec, ayuda demasiado y si usted no entiende, explica todas las veces que son necesarias. 20/10 si tiene la oportunidad matricule con él. En los exámenes da puntos por intentar o le rescata para que no le vaya tan mal.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd1a9999d9ee7c05b5f85c8d83efa4b9e2862ab9f98ebd82c556eb98f3c7650a4'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Por él se puede decir algo bueno de esa escuela. Si puede meter con él, no lo dude. Excelente profesor y aún mejor persona. Si un 10% de los profesores del TEC fueran cómo él y las señoras del comedor, la gente en el TEC serían menos infelices.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6339ce6354d7ad19faaf5a5399b33eb6bbbbe125f70398a45fc16724adb6f5b8'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Sin duda es un profesor excelente. Vela porque el estudiante de verdad aprenda y que muestre interés en su clase. Sus explicaciones son claras y explica las veces que sean necesarias. Por la parte personal es sumamente humilde y empático con los estudiantes. No dude en matricular con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1a28714e1f050c2db73b1d32116327c139d1e20c9bb787b87cd9100e607552e6'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es el mejor profe para Lab de física, ayuda mucho en las clases con los experimentos y califica suave los informes, incluso da más tiempo para los trabajos si es necesario y normalmente graba videos explicando lo que hay que hacer en los informes. Super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-12-27T00:00:00+00:00'::TIMESTAMPTZ, '8e94ac2fa0ddca85b8bef68bc46cac4874c8a8c4982ce6688b571ed4e09c1efe'::TEXT, ARRAY[631]::BIGINT[]),
    (205::BIGINT, 'Va a desear llevar todas las físicas con él, no dude en matricular con él. Muy ordenado, comprensivo, amable, es una excelente persona y muy empático, lo hace sentir en confianza, explica increíblemente bien, hace sesiones de repaso antes de exámenes, la consulta se aprovecha mucho, tiene vocación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '6a792489509b62e7b7a4381e805b8889e3d02e590119d6a483bc2450b75b05d1'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El mejor profesor del TEC para las físicas estoy seguro. Hace clases de repaso antes de los exámenes y en general se interesa mucho por que sus estudiantes entiendan. Sus presentaciones son muy claras. Si está como opción en alguna física HAGASE UN FAVOR y matricule con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2022-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'cad1367547acb80d97c76824c295422f9b13d03812f66b97e1d6afe682faa95f'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Un profe tremendo, no dude en matricular con él. Explica super bien, hace muchos ejemplos bien detallados, ayuda con las tareas, responde rápido y hace clases extra de repaso. La única pega es que sus clases se pasan 5 a 10 minutos de la hora indicada pero lo hace para que todo quede bien claro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e847ff419bf1fcd992fe76f983a5fd03aeb06d83e0b95c352d3940f50d3c9992'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Súper buen profe, deja las cosas súper claras. Es súper comprensible con los estudiantes y la materia se vuelve muy llevadera. Es como si lo llevara a uno de la mano pasito a pasito jajsjw. Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '8f938567a8c19f6b3286501d62b0cc8aacf78d0a838fbdd2785240062bd8e021'::TEXT, ARRAY[607]::BIGINT[]),
    (205::BIGINT, 'Tiene muchísimo conocimiento. Su dedicación en su labor como profesor es increíble. Está siempre dispuesto a ayudar y realmente le interesa que sus estudiantes aprendan. Sin embargo, las presentaciones que hace son muuuy largas. Repite muchísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, '295afeb4fd84ed01683c6037e9e96c4949e5ff79fb56af0bc20b9398ed35bcc4'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Súper recomendado, es bastante ordenado y explica con claridad. Si se tiene alguna duda él vuelve a explicar hasta que quede claro, inclusive con las tareas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-02T00:00:00+00:00'::TIMESTAMPTZ, 'be8ccf2ca10d38b990f12e3dfe628e43a41d3a8139a3b76a17663ad27facaa6f'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'De los mejores profes que he tenido, para mí explica súper bien y muchas veces él mismo durante la clase me resolvía las dudas que me surgían, me gustó mucho la forma en la que la desarrollaba la clase y es súper ordenado. Él siempre está dispuesto a ayudar y de verdad súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '931ca8a31f2a31098c13d2d4485f650d849c75289944b3f6782313b29e201fc5'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El profe explica muy bien, si no entiendes el se devuelve a explicar, en los trabajos no los dejes a ultimo momento ya que si no sabes hacer algo el profe te lo explica, es muy ordenado, en caso de tener alguna situacion personal que te afecte en alguna entrega si hablas con él se puede acordar algo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'eb24c3b96672e52c4599ca222081bc2517b27d0fe146a32a7f68db6398cf8fdb'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El profe es excelente ayuda muchisimo a todo y explica increiblemente bien! Matricule tranquil@ con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'ef75bfd6a1f7ec2e7e58e4efec9f1fd6ed194442761cd8ed047684ab61280b9a'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '15aa9f1c62213740ee255bc52aa5a09f7cf687242ae19735fe55f1b75d7c8fa5'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Se interesa mucho porque el estudiante comprenda los temas, explica muy bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, '7726ec15d0f6086cd89831b4738c80a596c4dcc5ae7a457e9289a9acedc34f4c'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El profe es demasiado bueno, da muchos consejos para hacer las tareas bien y sacarse toda la nota, siempre esta dispuesto a ayudar y se nota que sabe demasiado y le encanta lo que hace'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a95ede0bb49bf24824ca2b4ef279ca1d005c41f7efa1d6fac951e68f53f82632'::TEXT, ARRAY[604, 607]::BIGINT[]),
    (205::BIGINT, 'Explica de maravilla y prácticamente se pasa el curso solo asistiendo a clases. Las tareas son largas pero fáciles y solo hay que seguir las indicaciones que da el profe para salir bien, además de que siempre agarra una clase para dar consejos sobre la tarea.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '3155b69dec5ab94bd74762ad154b5e8f01075922f0c6096d250aed9eb4f0050c'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'De los mejores profes que he tenido, aclaraba todas las dudas que uno tuviera. Las tareas se hacían con lo que él explicaba en clase, los quices podían ser un poco difíciles en la parte práctica pero lo teórico se encontraba en el libro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '2d14a8eeb52174478a563c69a3020d80c6617328d86767aa3be22cf8632edc1b'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (205::BIGINT, 'Es un muy buen profesor, sabe usar muy bien la tecnología. Explica excelente y pide trabajos de calidad. El curso se pasa con hacer un grupo de amigos que llevan las clases con el mismo profe. Lo super recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'd21cb4cb69ffdb858a38dc55d24a93896303cfe15c4009a404ae34ece30b671a'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Por como se acomodó la catedra hay bastantes bretes, pero el da muchísimo apoyo para que a uno le vaya excelente. Atiende dudas rápido y de manera muy clara, y en las clases explica todo con mucha paciencia. Califica muy justo y es difícil sacarse una mala nota si se siguen los consejos que él da'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '30de05034682e05a98bfbe1511f7c8062e00bf2bbc039d7e93d055d3a50a1d7a'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es un profe excelente, da bastante ayuda cuando uno la necesita. Explica demasiado bien las clase. Super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'ca4a26a3f35b5935f282d9099039c82a53bbc494d5d2cfc483220e92290cba4b'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Bueno profe, ayuda bastante y explica muy bien'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'a9f6ec1192580a80442fdb919d8a8fcd97f1ef0d964b38dfccc1eebb8fe431ca'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Explica muy bien la materia, es atento a responder dudas, califica justo y en general, es buen profesor para llevar el curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'b1579de8036b20351cde1c5ec3e6c360f74ca88317fdb79dbad2eb3264591318'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Es un buen profesor, le interesa que uno aprenda, atento a las dudas y siempre tiene canales abiertos para las consultas cualquier día (sin importar que le hayas consultado muchas veces) se esmera por que entienda y si le toca repetir lo mismo para que lo entienda. Sabe mucho de power point.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'acbf6552f72c49876294e292a1f70c190b99e03eda113625ec52479cea8783a8'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Mae, es un amor, no lo deje ir, es demasiado cosi. Tiene empatía, es comprensivo, explica super bien, le interesa que usted entienda. Es como de los mejores profes que he tenido. Da una retroalimentación super buena. Se merece todo lo bueno que le pase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-12-22T00:00:00+00:00'::TIMESTAMPTZ, '8e8247253213a7ac9973b1ee964fc842aa75bc2910594e3330b01a82e691b41d'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (205::BIGINT, 'Este profe tiene doctorado en power point porque lo usa demasiado bien jaja, da clases muy ordenadas, explica lo ensencial ya que uno deberia ir preparado para la clase, explica con detalle y reiteración bastantes ejemplos que ya leva resueltos, lo que ayuda mucho, eso si, califica estricto.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'c640981bc864369e3c9a381badf66bbda672ea18757bd88410c1884c7f86a642'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Cuando era presencial: excelente, hacía muchos ejemplos de diferentes niveles, muy amable y claro a la hora de calificar. Excelente. SIN EMBARGO, virtual no era tan bueno. Hacía una sola clase eterna (como de 1 a 5), era muy lento para abarcar los diferentes puntos y duraba mucho en mandar las notas'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'd6c2164636ee74568f4f56695f9b2e16ae00ff2c78b37c501843d217fe7401c0'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Tanto la modalidad presencial como virtual fue muy buena con este profesor. Sus clases son bastante claras de entender, y siempre está dispuesto a resolver dudas durante clase y fuera de clase. Súper recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '2270500ce13b96238f8605b4c83735a0381f480d7b58524bf4e4ea6d457425ad'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El profe es buena nota pero es demasiado minusionso para calificar y baja puntos por cosas básicas, explica muy bien y da varios ejemplos que ayudan bastante. A la hora de calificar dura demasiado y hay que estarle preguntando por las notas porque dura de 3 a 4 semanas subiendo las notas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '2f54e74dbbd682cc17862c82a9839b924535aac4308c622aeb6b42f7f3e78293'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Excelente profesor. Mantiene contacto en todo momento con el estudiante por medio de Teams,. Ayuda muchisimo cuando uno está trabado con algun ejercicio de una tarea. Además se nota que sabe bastante. Recomendadisimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'e5a5f177867ad41b994233f8f30a708d725bfd8c645ca0871bb474d807a74746'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (205::BIGINT, 'En modalidad virtual es de los pocos que dan una clase semanal, en la que explica las asignaciones semanales. Califica justo, pero sí espera que aparte del procedimiento siempre vengan explicaciones teóricas. Si le da la hora de matrícula, meta con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '64e43484ee69be6df3d2b6dfca8d6fe7c9bd5d26d1c37c3d022d2ce68bca87e7'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (205::BIGINT, 'Revisa muy suave, para la modalidad virtual estuvo bien, todas las semanas hacía un período de consulta donde explicaba semanalmente que había que hacer. Respondía todas las consultas por teams'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '8fe75cb4e15e6a927d0a5aa9977ef583f3530574bf1673421f562b8e115d06e6'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Excelente profe. Explica súper bien y se nota el interés de que todos aprendan bien. Le interesa que usted entienda y sea explícito en el procedimiento más que usted tenga la respuesta buena, entonces en ese sentido califica suave. Es súper buena gente y paciente, siempre intenta de ayudar a todos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '21c2a46ce922ed1a1ae7b57a931b9dba8b6b9270fc6e646df50c4719fc9d3912'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Las pocas clases presenciales fue super claro. Tiene mucha paciencia, le importa que usted aprenda. Sorprendentemente es un profesor de física con empatía. NO LO DEJE IR. Si tuviera tablet sería un 10/10 para clases virtuales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'a5d54f45a5833c75b1e935d3f61f0b4b0d725b194fcc6d31c136a3cac7bcd3aa'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El profe explica bien, da consulta y explica todo lo que usted necesite, se le entiende súper. No contesta los correos, entonces cuesta contactarlo si no es en la clase o por teams.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '7ab2f8049cc286455dbcd620e716d98ad0f7ff2ce809566a21e784c756430cb9'::TEXT, ARRAY[630]::BIGINT[]),
    (205::BIGINT, 'Bastante claro a la hora de explicar, siempre está dispuesto a brindar ayuda y califica de manera justa sus evaluaciones, es claro con los aspectos que se evalúan de sus evaluaciones y en general permite una gran comprensión de la materia'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2020-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'afc9797f42f00a09fddf9caddc98ab8a57a34c82416962e88e930b0012388021'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Un profesor que se interesa por los alumnos y es sumamente claro al explicar. Califica suave si uno sigue sus recomendaciones. Puede ser que se atrase un poco entregando las evaluaciones pero siempre esta dispuesto a aclarar cualquier duda de la mejor manera. Recomendadísimo!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '1be9655c23a9c86d413498e36b040fd465c7063f6c7172be57c3c30d62fe3860'::TEXT, ARRAY[607]::BIGINT[]),
    (205::BIGINT, 'Es justo al calificar, es muy accesible para las preguntas, se da a entender bastante bien, da muchos ejemplos de ejercicios muy parecidos a los del examen, quiero llevar más físicas con él'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'd2f6f2c9760e1ab1188a371294f83a227d5de0a4b9066cc2f87c63312f4663b1'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El profe se preocupa mucho por el aprendizaje de los estudiantes, no le gusta regalar puntos y con eso sí es un poco estricto pero toma mucho en cuenta el interés de los estudiantes, los reportes los califica duro pero en general es demasiado buen profe y tiene pasión por lo que hace.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '9efef31652688ae09ec12c531dbccf11b73dda024311676857270a8b02cd41d4'::TEXT, ARRAY[607]::BIGINT[]),
    (205::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, '955e94e00fe838fc747ac53cf392cfa5f4beda711777a898bce902dbb06abb3b'::TEXT, ARRAY[607]::BIGINT[]),
    (205::BIGINT, 'Creo que es de los mejores profes de la cátedra, solo bastante desordenado. Explica bastante bien, en si hay que tenerle cuidado al curso y no al profe, no confiarse y repasar bastante para los exámenes. Haga todos los quices y proyectos que hayan porque suben mucho y fácilmente la nota!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, '3d6a1de2a265aa5d20730eaabdb5acea270f12d0a4e117d4181a6fd9902f2d2c'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'No se,a nivel de clase no esta tan mal, pero no te deja un aprendizaje real, como profesor no aporta demasiado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2019-12-17T00:00:00+00:00'::TIMESTAMPTZ, '37e3305a13fd5e452a100d851c4e77101646b0adacaeb9104fc52b6baa30aee3'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Hay que estudiar para los quices, explica bastante bien, los reportes los califica duro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '9e5ffd7144bd93994db0bdfe918188945ff7d7ec04386cee4c39abf40ef52c2d'::TEXT, ARRAY[607]::BIGINT[]),
    (205::BIGINT, 'Es un excelente profe, se preocupa mucho porque el estudiante realmente aprenda. Explica con muchos ejercicios, no se enfoca tanto en la teoría. Lo malo es que es muy desordenado en la pizarra y eso a veces tiende a confundir, pero en lo demás es buenísimo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '3dba6b116e7fe8fd5769344b8aa96a9653d969dad2bac7847d03cd6a14683dcc'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Un dios de la enseñanza, 11/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-10-13T00:00:00+00:00'::TIMESTAMPTZ, '7146e7e3640d8ea1d52f70dd56983b05747372d53e7ec0c7afcfe0c5e8110a97'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Es un amor. Explica demasiado bien, califica muy justo y es una belleza en consulta. Por él hubiera repetido el curso con gusto pero no sucede porque, pfff, es él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2019-07-23T00:00:00+00:00'::TIMESTAMPTZ, '4d7a31ceafee9b22a5cc3dfbb8f1b0f6de4100e5910bed6257bd84ac3881163e'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Demasiado buen profesor, se interesa mucho mas porque el alumno aprenda que por las notas, ayuda en todo y sino se queda todo lo necesario en consulta. Super recomendado, lastima que no da las otras fisicas...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b9d47a6f9a4a10906a35580ea6718ececd6e05af231ab9954fbd84ddd93ab60d'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Excelente, califica suave. Súper buena nota'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, '89dbd922d8f5fbafc5f48b10702c0838960b7ef9489579657d42f494ffd74b84'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'b7b0e86bf98faa483f9d4005a3232b1c39d725e604a8a47f4feda56e5da17a37'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'El mae en serio se esfuerza para que todos los estudiantes aprendan, y hay que poner atención a los tips que da para el examen, con las notas escritas y esas varas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c577f6c4f169cb35b3d6d3d9857f65e58353c35b7465c1b480a4f8fb09a39216'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Explica bien y es buen profesor, se interesa en que los estudiantes sepan lo que estan haciendo. Lo unico que enreda un poco es que a veces no resuelve algunas operaciones en los ejercicios y los sigue trabajando como variables.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '5feddcd10a7d7c220b6717bc841d968b61936347c0cfc11601c86d9fa857b7f7'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '8926b9f0076e161c7423dcacd2f1eff7932384c8c7dc5b8893506a870673359b'::TEXT, ARRAY[604]::BIGINT[]),
    (205::BIGINT, 'Excelente profesor, los quices son faciles, y todo lo evalua muy justo, se pasa facil'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'c4c43303bd9bbc6fd2144d2eecc69948642253e3b9eda2b5f66b7de6eb1952ae'::TEXT, ARRAY[604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
